// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { InfoBlockProps } from "./info-block.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "InfoBlock";

// Generate child element class names for the component, should match available style slots
export const InfoBlockClasses = {
  root: "exp-textura_info-block",
  visual: "exp-textura_info-block_visual",
  content: "exp-textura_info-block_content",
  title: "exp-textura_info-block_title",
  subtitle: "exp-textura_info-block_subtitle",
  sublink: "exp-textura_info-block_sublink",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: InfoBlockProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<InfoBlockProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-flex",
    alignItems: "center",
    gap: theme.toRem(theme.spacing[8]),

    [`.${InfoBlockClasses.visual}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      borderRadius: theme.toRem(theme.border.radius.sm),
      ...styleSlots?.visual,
    },

    [`.${InfoBlockClasses.content}`]: {
      display: "flex",
      flexDirection: "column",
      overflow: "hidden",
      ...styleSlots?.content,
    },

    [`.${InfoBlockClasses.title}`]: {
      ...theme.typography.body.md,
      color: theme.color.content.default,
      overflow: "hidden",
      textOverflow: "ellipsis",
      ...styleSlots?.title,
    },

    [`.${InfoBlockClasses.subtitle}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[4]),
      ...theme.typography.body.sm,
      color: theme.color.content.weak,
      overflow: "hidden",
      textOverflow: "ellipsis",
      lineHeight: theme.typography.lineHeight[16],
      ...styleSlots?.subtitle,
    },

    [`.${InfoBlockClasses.sublink}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[4]),
      ...theme.typography.body.sm,
      color: theme.color.content.weak,
      overflow: "hidden",
      textOverflow: "ellipsis",
      lineHeight: theme.typography.lineHeight[16],
      ...styleSlots?.sublink,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledInfoBlock = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<InfoBlockProps>((props) => generateStyles(props));
